"""OUT/README.md and the header line of generated files: what each file is for, who writes it, whether it is committed."""
from pathlib import Path

GUIDE_URL = "https://si1verwind17.github.io/codebase-map/"   # the field guide: how to read the map

HEADER = ("<!-- Generated by the visualizing-codebases skill ({script}); {purpose}. "
          "Do not edit: the next run overwrites it. -->")

# (file, what it is for, written by, committed) — the rows of the README table, in order
FILES: list[tuple[str, str, str, bool]] = [
    ("code-map.json", "the map: every fact, stamped with one commit", "`assemble.py` from the agent's `meaning.json`", True),
    ("stack.yaml", "libraries and route styles this repo uses that the scanner does not know built in",
     "the agent; you may edit", True),
    ("map-notes.md", "your standing notes on the map", "you", True),
    ("README.md", "this file", "`assemble.py`", True),
    ("index.html", "the map viewer page", "`assemble.py`, `view.py`", False),
    ("audit.md", "drawing and content checks, findings", "`assemble.py`, `audit.py`", False),
    ("structure.json", "the scanner's facts, and the digest the agent reads", "`extract.py`", False),
    ("summary.md", "the scanner's facts, and the digest the agent reads", "`extract.py`", False),
    ("meaning.json", "the agent's working facts and the incremental plan", "the agent, `diff.py`", False),
    ("meaning.previous.json", "the agent's working facts and the incremental plan", "the agent, `diff.py`", False),
    ("stale.json", "the agent's working facts and the incremental plan", "the agent, `diff.py`", False),
    ("export-comment.md", "review comments and pin changes exported from the viewer", "the viewer, by you", False),
    ("code-map.invalid.json", "a rejected map, kept for fixing", "`assemble.py`", False),
]

# several files share one table row
_ROWS = [["code-map.json"], ["stack.yaml"], ["map-notes.md"], ["README.md"], ["index.html"],
         ["audit.md"], ["structure.json", "summary.md"], ["meaning.json", "meaning.previous.json", "stale.json"],
         ["export-comment.md"], ["code-map.invalid.json"]]


def header(file: str) -> str:
    """The generated-file comment for `file`: the script that writes its content, and what it is for."""
    _, purpose, by, _ = next(r for r in FILES if r[0] == file)
    return HEADER.format(script=by.replace("`", ""), purpose=purpose)


def write(out: Path) -> None:
    """OUT/README.md, overwritten on every run."""
    by_name = {r[0]: r for r in FILES}
    rows = []
    for names in _ROWS:
        r = by_name[names[0]]
        files = ", ".join(f"`{n}`" for n in names)
        rows.append(f"| {files} | {r[1]} | {r[2]} | {'yes' if r[3] else 'no'} |")
    text = "\n".join([
        f"# {out.name}", "",
        "This folder was generated by the visualizing-codebases skill. To refresh it, run the skill again; "
        "files marked committed belong in git, the rest are working files, already gitignored.", "",
        f"How to read the map: the field guide at {GUIDE_URL}", "",
        "| File | What it is for | Written by | Committed |", "|---|---|---|---|", *rows, ""])
    (out / "README.md").write_text(text, encoding="utf-8")
